const inputData = $input.first().json || {};
const { reviewId, content, userId, username, email, timestamp } = inputData;

const promptText = `Analiza el siguiente comentario de reseña para determinar si contiene lenguaje ofensivo, insultos, agresión, spam o contenido dañino para alguien. 

Comentario: "${content}"

Responde JSON con esta estructura exacta:
{
  "offensive": true/false,
  "severity": "low|medium|high", 
  "category": "insult|aggression|spam|harassment|other",
  "explanation": "Explicación breve del hallazgo",
  "actionRequired": true/false,
  "suggestedSuspensionDays": number (0-365)
}

Sé objetivo. Si hay algún término ofensivo en cualquier idioma, establece offensive=true. Sé conservador con severity: low para términos leves, medium para insultos moderados, high para agresión seria o acoso.
`;

return [{
  json: {
    promptText,
    metadata: {
      reviewId,
      content,
      source: 'gemini-openrouter'
    }
  }
}];

const inputData = $input.first().json || {};
const { text, response } = inputData;

let analysisResult = {
  offensive: false,
  severity: 'low',
  category: 'other',
  explanation: 'Análisis completado por IA.',
  actionRequired: false,
  suggestedSuspensionDays: 0
};

try {
  let responseText = '';

  if (response.output) {
    responseText = String(response.output);
  } else if (response.text) {
    responseText = String(response.text);
  } else if (typeof response === 'string') {
    responseText = response;
  } else {
    responseText = JSON.stringify(response);
  }

  const parsed = JSON.parse(responseText);

  if (parsed.offensive !== undefined) {
    analysisResult = {
      offensive: Boolean(parsed.offensive),
      severity: parsed.severity || 'low',
      category: parsed.category || 'other',
      explanation: parsed.explanation || 'Sin explicación',
      actionRequired: parsed.actionRequired !== undefined ? Boolean(parsed.actionRequired) : true,
      suggestedSuspensionDays: Number(parsed.suggestedSuspensionDays) || 0
    };
  } else {
    const lowerText = String(responseText).toLowerCase();
    const offensiveTerms = ['idiota', 'imbécil', 'mierda', 'puta', 'pendejo', 'hijo de', 'spam', 'odio', 'muérete', 'muerete'];
    const foundTerms = offensiveTerms.filter(term => lowerText.includes(term));

    if (foundTerms.length > 0) {
      analysisResult.offensive = true;

      if (foundTerms.some(t => ['mierda', 'spam', 'odio'].includes(t))) {
        analysisResult.severity = 'medium';
      } else {
        analysisResult.severity = 'low';
      }
      analysisResult.category = 'insult';
      analysisResult.explanation = `Términos ofensivos detectados: ${foundTerms.join(', ')}`;
      analysisResult.actionRequired = true;
      analysisResult.suggestedSuspensionDays = 30;
    } else {
      analysisResult.explanation = 'No ofensivo - contenido limpio.';
    }
  }
} catch (err) {
  console.error('[AI Agent] Error parsing response:', err);
  analysisResult.explanation = 'Error procesando respuesta IA, revisar manualmente.';
}

return [{
  json: {
    ...analysisResult,
    metadata: {
      reviewId: inputData.metadata?.reviewId,
      source: 'ai-analysis'
    }
  }
}];

const inputData = $input.first().json || {};
const { offensive, severity, category, explanation, suggestedSuspensionDays, userId, username, email, metadata } = inputData;

// Determinar la acción basada en la severidad
let action = 'finalize';
let suspensionDays = 0;
let shouldSuspend = false;
let shouldDelete = false;
let shouldSendWarning = false;
let warningType = 'no-action';

switch (severity) {
  case 'high':
    action = 'suspend';
    shouldSuspend = true;
    shouldDelete = true;
    suspensionDays = Math.max(1, Number(suggestedSuspensionDays) || 30);
    warningType = 'suspension';
    break;
  case 'medium':
    action = 'warn';
    shouldSuspend = false;
    shouldDelete = true;
    suspensionDays = 7;
    warningType = 'medium-warning';
    break;
  case 'low':
  default:
    action = 'flag';
    shouldSuspend = false;
    shouldDelete = false;
    suspensionDays = 0;
    warningType = 'low-flag';
    break;
}

// Construir datos de suspensión si es necesario
let suspensionData = null;
if (shouldSuspend) {
  suspensionData = {
    userId: userId || 'N/A',
    username: username || 'Usuario Desconocido',
    email: email || 'usuario@sonar.com',
    reason: `Reseña ofensiva [${severity}]: ${explanation || 'Sin detalles'}`,
    severity: severity,
    suspensionDays: suspensionDays,
    performedBy: 'Sistema IA - Moderación Automática',
    timestamp: new Date().toISOString()
  };
}

return [{
  json: {
    ...inputData,
    action,
    suspensionData,
    shouldSuspend,
    shouldDelete,
    shouldSendWarning: warningType !== 'no-action' && warningType !== 'low-flag',
    warningType,
    suspensionDays,
    processedAt: new Date().toISOString()
  }
}];
